// Generated by scripts/build-coin-availability.mjs from content-source/coins/descriptions. Do not edit by hand.
// NexuAlpha's own coin descriptions (zh-Hans).
export const COIN_DESCRIPTIONS = Object.freeze({"a7a5":"A7A5 是锚定俄罗斯卢布的稳定币，2025 年由一家在吉尔吉斯斯坦注册的公司推出，以存放在俄罗斯银行的卢布存款作为支撑。它运行在以太坊和 TRON 上，用于跨境结算。该代币及其发行方已被美国、英国和欧盟列入制裁名单，这会影响其可使用的范围和方式。","aave":"AAVE 是去中心化借贷协议 Aave 的治理代币。在 Aave 上，用户可以存入加密资产供他人借用，也可以用自己的抵押品借款。持有者可对升级和风险参数投票，还可质押 AAVE 以帮助弥补系统可能出现的资金缺口。项目始于 2017 年的 ETHLend，原 LEND 代币于 2020 年兑换为 AAVE。","aerodrome-finance":"AERO 是 Aerodrome Finance 的代币。Aerodrome 是运行在 Base（由 Coinbase 推出的以太坊二层网络）上的去中心化交易与流动性平台，于 2023 年上线，沿用了 Velodrome 的设计。持有者可将 AERO 锁定为 veAERO，投票决定新增代币排放流向哪些流动性池，并获得所支持池子的部分交易手续费和激励。","agora-dollar":"AUSD 是 Agora 于 2024 年推出的美元稳定币。每枚代币由现金、短期美国国债和隔夜回购协议支持，储备由 VanEck 管理、道富银行（State Street）托管。它用于支付、交易和 DeFi，发行在以太坊、Sui、Mantle、Injective、Polygon、Monad 等多条网络上。","akash-network":"AKT 是 Akash Network 的原生代币。Akash 是一个去中心化云计算市场，用户可以出租或租用算力，包括用于 AI 训练和推理的 GPU。它基于 Cosmos SDK 构建，AKT 用于质押保障网络安全、参与治理和支付算力费用。服务商通过公开竞价为每次部署报价。","akedo":"Akedo（AKE）是 BNB Smart Chain 上的一枚代币，归属 AI 赛道。项目围绕 AI 工具展开，AKE 作为生态代币用于参与和激励。","algorand":"Algorand（ALGO）是 Algorand 区块链的原生币，该链由麻省理工学院教授、图灵奖得主 Silvio Micali 创立，2019 年上线。它采用纯权益证明（Pure PoS），出块者从持币人中随机选出。ALGO 用于支付交易费和保障网络安全，该链常被用于资产代币化和支付。","ape-and-pepe":"Ape and Pepe（APEPE）是一种结合了猿猴和青蛙 Pepe 两个网络形象的模因币，运行在转账费用较低的 Polygon PoS 网络上。和大多数模因币一样，它没有核心协议功能，关注度主要来自社区和交易活动。","apenft":"NFT 是 AINFT（原名 APENFT）的代币，项目于 2021 年在波场（TRON）生态推出。它最初旨在把知名艺术品以 NFT 形式上链并运营 NFT 市场，改名后的方向扩展到 AI 相关服务。该代币在平台内使用，存在于 TRON、以太坊和 BNB Smart Chain 上。","aptos":"APT 是 Aptos 的原生代币。Aptos 是一条采用权益证明的一层区块链，主网于 2022 年上线，由曾参与 Meta 旗下 Diem 区块链的工程师创立，智能合约使用 Move 编程语言。APT 用于支付交易费，由验证者和委托人质押以保障网络安全，并用于治理。","apxusd":"apxUSD 是一种锚定美元的稳定币，发行在以太坊、Base、BNB Smart Chain 和 Solana 上。它设计为保持约 1 美元的价值，作为这些网络上转账、交易和 DeFi 应用的稳定计价单位。","arbitrum":"ARB 是 Arbitrum 的治理代币。Arbitrum 是由 Offchain Labs 开发、采用 Optimistic Rollup 技术的一组以太坊二层网络。持有人在 Arbitrum DAO 中就升级和财库支出投票，而 Arbitrum One 上的交易费用以 ETH 而非 ARB 支付。该代币于 2023 年 3 月通过空投分发。","arweave":"AR 是 Arweave 的原生代币。Arweave 是一条专注永久数据存储的区块链，2018 年上线。用户一次性支付 AR 即可存储文件，部分费用进入长期存储基金，矿工则通过保存数据获得 AR。Arweave 上还运行着 AO，这是面向自主程序和 AI 智能体的计算层。","aster-2":"ASTER 是 Aster 的代币。Aster 是一个以永续合约和现货交易为主的去中心化交易所，主要运行在 BNB Chain 上。该代币用于治理、激励以及平台上与手续费相关的权益，于 2025 年推出，以 BNB Smart Chain 代币形式持有。","avalanche-2":"Avalanche（AVAX）是Avalanche区块链平台的原生代币，由Ava Labs于2020年推出。AVAX用于支付交易费（费用会被销毁），并由验证者在权益证明机制下质押。Avalanche的C链兼容以太坊智能合约，项目还可以发行自己的定制区块链，AVAX总量上限为7.2亿枚。","axie-infinity":"AXS 是《Axie Infinity》的治理与质押代币。这款区块链游戏由越南工作室 Sky Mavis 开发，玩家可以收集、繁殖名为 Axie 的小精灵并进行对战。持有者可质押 AXS，并就社区金库事务投票，游戏内的繁殖等操作也会消耗 AXS。游戏主要运行在 Sky Mavis 专门打造、与以太坊相连的 Ronin 链上。","backpack":"BP 是与 Backpack 相关的代币。Backpack 是从 Solana 生态成长起来的加密货币交易所和自托管钱包，由 Mad Lads NFT 系列背后的团队运营。BP 以 SPL 代币形式发行在 Solana 上，用于连接平台生态和社区计划，具体用途由 Backpack 团队规定。","basic-attention-token":"BAT（Basic Attention Token）是与 Brave 浏览器绑定的 ERC-20 代币，Brave 默认屏蔽大部分追踪器和广告。用户选择观看 Brave 的隐私友好型广告后可获得 BAT，并可用它支持网站和内容创作者。BAT 于 2017 年推出，之后被桥接到 Solana、Polygon 等多个网络。","beldex":"BDX 是 Beldex 的原生币。Beldex 是基于门罗币（Monero）代码开发的隐私区块链，2018 年上线，借助环签名和隐身地址等技术隐藏交易细节。其主节点网络支持隐私通讯 BChat 和去中心化 VPN BelNet。BDX 用于支付交易费并由主节点运营者质押，在 BNB Smart Chain 上也有 BEP-20 版本。","bfusd":"BFUSD 是币安推出的美元计价资产，只在币安平台内部使用，并不运行在公链上。它主要用作合约交易的保证金，相关规则由币安制定，而不是由链上协议决定。与常见稳定币不同，它并非为在钱包之间自由转账而设计。","bianrensheng":"币安人生（BinanceLife）是 BNB Smart Chain 上的一枚 Meme 代币，名字是对币安生态的一种调侃。它在 2025 年于中文加密社区中走红。该代币没有协议用途、手续费功能或资产支撑，价值完全取决于社区关注度。","binancecoin":"BNB是BNB Chain的原生币，与币安生态紧密相关。它于2017年以以太坊代币形式推出，之后迁移到自己的网络，用于支付Gas费、由验证者质押以及参与治理。BNB设有定期销毁机制，会持续把一部分币永久移出流通。","bitcoin":"比特币（BTC）是第一种加密货币，由化名中本聪的开发者于2009年推出。它运行在自己的工作量证明区块链上，由矿工维护网络并确认交易，人们用它转账，也把它当作长期价值储存。比特币总量上限为2100万枚，新区块奖励大约每四年减半一次。","bitcoin-cash":"比特币现金（BCH）是2017年8月通过比特币硬分叉产生的加密货币。支持者希望扩大区块，让网络以低费用处理更多交易，更适合日常支付。BCH运行在自己的工作量证明区块链上，沿用比特币2100万枚的总量上限和减半规则，主要用于点对点支付。","bitcoin-cash-sv":"Bitcoin SV（BSV）是一种工作量证明加密货币，于 2018 年 11 月从比特币现金（BCH）分叉而来。包括 nChain 在内的支持者希望遵循他们所理解的比特币原始设计，采用超大区块以实现高链上吞吐量。BSV 使用 SHA-256 挖矿，总量上限 2100 万枚，用于支付和数据密集型应用。","bitget-token":"Bitget Token（BGB）是 Bitget 交易所生态的功能型代币。持有人可用它享受交易手续费折扣、参与新币发行活动，它同时也是以太坊二层网络 Morph 的 Gas 代币。2024 年底，Bitget 将 Bitget Wallet Token（BWB）并入 BGB，并销毁了大量供应。","bittensor":"TAO 是 Bittensor 的原生币。Bittensor 是一个去中心化网络，参与者提供机器学习模型和算力，并根据产出的实用程度获得奖励。网络划分为多个专门的子网，TAO 用于质押、注册子网和支付服务费用。与比特币类似，TAO 最大供应量为 2,100 万枚，新增发行量会定期减半。","bittorrent":"BitTorrent（BTT）是与 BitTorrent 文件分享软件相关的代币，诞生于 2018 年波场创始人孙宇晨旗下公司收购 BitTorrent Inc. 之后。BTT 用于奖励加速做种的用户、支付 BTFS 去中心化存储费用，并作为 BitTorrent Chain 的 Gas 代币。该代币在 2021 年按 1 枚旧 BTT 兑 1000 枚新 BTT 的比例进行了重新面额调整。","bitway":"Bitway（BTW）是一个去中心化金融（DeFi）项目的代币，以代币形式发行在 BNB Smart Chain 和以太坊上，可存放在这两条链的常用钱包中。","blockchain-capital":"BCAP 是风险投资机构 Blockchain Capital 于 2017 年发行的数字证券，代表其旗下一只风险投资基金的经济权益。它是最早的代币化投资基金之一，以以太坊代币的形式发行。由于 BCAP 属于证券而非功能型代币，其持有和转让都受证券法规及投资者资格要求的约束。","blockstack":"STX 是 Stacks 的原生代币，Stacks 前身名为 Blockstack，是比特币上的智能合约层。它采用名为“转移证明”（Proof of Transfer）的共识机制：矿工投入 BTC 参与出块，链上状态最终结算到比特币。STX 用于支付交易和 Clarity 智能合约的费用，持有者还可通过“stacking”锁定 STX，帮助保障网络安全。","bnb48-club-token":"KOGE 是 48 Club（又称 BNB48 Club）的代币，这是一个历史较长的 BNB 持有者社区。该社区在 BNB Smart Chain 上运营验证节点及相关基础设施，KOGE 用于社区会员资格和治理。它是 BNB Smart Chain 上发行的 BEP-20 代币。","bonk":"Bonk（BONK）是 Solana 上的狗狗主题 Meme 币，于 2022 年 12 月推出，当时一半供应量空投给了 Solana 用户、开发者和 NFT 社区。它既不是稳定币也不是治理代币，主要作为社区代币，用于打赏以及交易机器人、游戏等 Solana 应用。以太坊、BNB Smart Chain、Arbitrum 等网络上也有其跨链版本。","canton-network":"Canton Coin（CC）是Canton Network的原生代币。这是一条面向受监管金融机构的区块链，技术由Digital Asset公司开发。Canton让不同应用在保护数据隐私的同时，仍能相互结算交易。CC用于支付网络费用，并奖励维持网络运行的验证者和应用提供方。","cardano":"卡尔达诺（ADA）是2017年上线的权益证明区块链，由以太坊联合创始人Charles Hoskinson领导的团队以学术研究方式开发。ADA用于支付交易费、委托给质押池以通过Ouroboros协议保障网络，并参与治理投票。ADA得名于Ada Lovelace，总量上限为450亿枚。","celestia":"Celestia 是一条专注于数据可用性的模块化区块链，负责存储和发布交易数据，让 Rollup 等链无需自建完整的共识层。TIA 用于支付向网络提交数据（Blob）的费用、质押以保障权益证明网络安全，并参与治理。主网于 2023 年 10 月上线，基于 Cosmos SDK 构建。","chain-2":"Onyxcoin（XCN）是 Onyx 项目的代币。该项目的前身是 2022 年推出 XCN 的 Chain，之后更名为 Onyx。XCN 用于 Onyx 协议的治理，以及在其生态内支付费用，该生态还包括自有的 Onyx 链。这枚代币同时存在于以太坊、Base 和 BNB Smart Chain 上。","chainlink":"Chainlink（LINK）是一个去中心化预言机网络的代币，负责把资产价格等链下数据提供给智能合约。LINK用于向节点运营者支付服务费用，也可以质押来帮助保障预言机服务。Chainlink还运营跨链通信协议CCIP，其价格数据被众多DeFi和代币化资产项目采用。","collector-crypt":"CARDS 是 Collector Crypt 的代币。Collector Crypt 是 Solana 上的项目，把经过评级的实体卡牌（例如宝可梦卡）代币化，实物存放在专业保管库中。每张卡对应一个 NFT，可在链上交易，也可兑换实物。CARDS 代币与平台生态挂钩，包括数字卡包开启和社区激励等。","compound-governance-token":"COMP 是 Compound 的治理代币。Compound 是以太坊上最早的借贷协议之一，用户可把加密资产存入资金池，或抵押资产借款。COMP 持有者可以提出并投票决定支持哪些资产、利率模型如何设置等。总量上限 1000 万枚，2020 年 6 月开始向协议用户分发。","conflux-token":"Conflux（CFX）是 Conflux 网络的原生代币，该公链于 2020 年上线主网。它采用树图（Tree-Graph）结构并行处理区块，并把工作量证明挖矿与权益证明最终性层结合起来。CFX 用于支付手续费、作为合约存储的抵押和参与 PoS 质押；网络还提供兼容以太坊的 eSpace。","convex-finance":"CVX 是 Convex Finance 的代币，该协议于 2021 年在以太坊上线，构建在 Curve 交易所之上。Convex 让 Curve 流动性提供者和 CRV 持有者无需自行锁仓 CRV 也能获得加成奖励。CVX 持有者可将代币锁定为 vlCVX，投票决定 Convex 掌握的大量 Curve 投票权如何分配，并分享协议费用。","cosmos":"ATOM 是 Cosmos Hub 的原生代币，Cosmos Hub 于 2019 年上线，是 Cosmos 生态中的第一条链。ATOM 用于质押以保障权益证明网络安全、支付交易手续费，并让持有者参与链上治理投票。Cosmos Hub 通过跨链通信协议（IBC）与众多独立区块链相连，因此 ATOM 也出现在 Osmosis、Kava 等网络上。","crvusd":"crvUSD 是 Curve Finance 于 2023 年推出的美元稳定币。用户存入 ETH、封装比特币等加密资产作为抵押来铸造，属于超额抵押。它的特色是 LLAMMA 机制：价格下跌时逐步转换抵押品，而不是一次性清算。crvUSD 在以太坊和多个二层网络的 DeFi 中使用。","crypto-com-chain":"Cronos（CRO）原名 Crypto.com Coin，是 Cronos 区块链的原生代币，由 Crypto.com 背后的团队推出。CRO 用于支付 Cronos EVM 链上的 Gas 费、质押以帮助保障网络安全，也用于 Crypto.com 生态中的奖励和权益。它在以太坊上也以 ERC-20 代币形式存在。","curve-dao-token":"CRV 是 Curve Finance 的治理代币。Curve 是 2020 年上线的去中心化交易所，专注于稳定币等同类资产之间的低滑点兑换。持有者可将 CRV 锁定最长四年换取 veCRV，从而获得投票权、交易手续费分成，并决定 CRV 奖励流向哪些资金池。CRV 已跨链到 Arbitrum、Polygon 等多个网络。","dai":"Dai（DAI）是一种去中心化稳定币，目标是与 1 美元保持一致。用户在智能合约中锁定价值高于所铸 DAI 的加密资产作为抵押，即可生成 DAI；该系统最初由 MakerDAO 运营，后者现已更名为 Sky。DAI 广泛用于 DeFi 中的交易、借贷和支付，以以太坊代币形式运行。","dash":"达世币（DASH）于 2014 年推出，最初名为 XCoin 和 Darkcoin，定位于快速、低成本的支付。网络将工作量证明挖矿与主节点结合，主节点支持 InstantSend 近乎即时确认，以及基于 CoinJoin 的混币功能以增强隐私。每个区块奖励中有一部分进入国库，由主节点持有者投票决定资金用途。","decentraland":"MANA 是 Decentraland 的代币。Decentraland 是一个 3D 虚拟世界，用户以以太坊 NFT 的形式拥有土地地块；项目于 2017 年进行代币发售，2020 年向公众开放。MANA 可用于购买土地（LAND）、虚拟形象服饰、名称等物品，持有者还能通过 Decentraland DAO 对规则和资助进行投票。它是以太坊上的 ERC-20 代币，并已桥接到 Polygon。","decred":"Decred（DCR）是 2016 年推出的加密货币，结合了工作量证明挖矿和权益证明投票：持有者锁定 DCR 换取票券，用来确认区块和对规则变更投票。每个区块奖励的一部分进入金库，支出由持币者投票决定。DCR 总量上限为 2100 万枚，网络内置 StakeShuffle 混币功能，提供可选的隐私保护。","derive":"Derive（DRV）前身为 Lyra Finance，是一个提供链上期权、永续合约和结构化产品的去中心化交易所。它运行在自有 Rollup——基于 OP Stack、结算到以太坊的 Derive Chain 上。DRV 用于治理和质押，质押者可获得与交易所活动相关的权益。","dogecoin":"狗狗币（DOGE）由Billy Markus和Jackson Palmer于2013年作为玩笑创建，形象来自“doge”柴犬表情包。它运行在自己的工作量证明区块链上，采用Scrypt算法，常与莱特币联合挖矿。DOGE多用于打赏和小额支付，没有固定的总量上限。","dogwifcoin":"WIF（dogwifhat）是 Solana 上的模因币，形象是一只戴着粉色针织帽的柴犬。它于 2023 年底推出，成为辨识度很高的 Solana 模因代币之一。除了被社区交易和传播外，它没有协议功能，在 Unichain 上也有对应版本。","doublezero":"2Z 是 DoubleZero 的代币。该网络项目为区块链验证者提供专用的高带宽光纤线路，以替代普通的公共互联网。项目首先服务于 Solana，2Z 以 SPL 代币的形式发行在 Solana 上。该代币用于支付网络使用费用，并奖励提供带宽和基础设施的贡献者。","eigenlayer":"EIGEN 是 EigenCloud（原名 EigenLayer）的代币。它是以太坊上的再质押协议，允许已质押的 ETH 再次质押，为数据可用性层、预言机和可验证 AI 计算等服务提供以太坊的经济安全。EIGEN 本身可质押，用于保障难以在链上证明错误的任务，也可在 Base 上使用。","ethena":"ENA 是 Ethena 协议的治理代币。Ethena 发行合成美元 USDe，它不依赖银行存款，而是用加密资产加上对冲的期货空头头寸作为支撑，使其价值保持在 1 美元附近。ENA 持有者可对风险和协议事项投票，也可质押该代币。ENA 于 2024 年在以太坊上推出。","ethena-usde":"Ethena USDe是Ethena于2024年推出的合成美元，目标是保持接近1美元。它并非由银行存款支持，而是持有ETH、BTC等加密抵押品，并用期货空头头寸对冲价格波动，即所谓的“Delta中性”策略。USDe用于交易和DeFi，可在多条网络上使用。","ether-fi":"ETHFI 是 ether.fi 的治理代币，ether.fi 是以太坊上的流动性质押与再质押协议。用户存入 ETH 后可获得 eETH 或 weETH，这些代币代表已质押的 ETH，并通过 EigenLayer 再质押，为其他服务提供安全保障。ETHFI 于 2024 年发行，持有者可对协议事项投票；项目还推出了加密支付卡。","ethereum":"以太币（ETH）是以太坊的原生货币。以太坊于2015年上线，可运行智能合约和去中心化应用。ETH用于支付交易费（Gas），并由验证者质押来保障网络安全；以太坊在2022年由挖矿转为权益证明。大量代币、稳定币和DeFi应用建立在以太坊上，每笔交易费的一部分会被销毁。","ethereum-classic":"以太经典（ETC）是 2016 年 The DAO 黑客事件引发分叉后，继续按原规则运行的以太坊原始链。它仍采用工作量证明（PoW）挖矿，支持与以太坊工具兼容的智能合约。ETC 用于支付交易费并奖励矿工，总供应上限约为 2.107 亿枚。","ethereum-name-service":"ENS 是以太坊域名服务（Ethereum Name Service）的治理代币。该服务把 alice.eth 这样易读的名字映射到钱包地址等信息。持有者可在 ENS DAO 中对提案投票，管理协议和金库。这个 ERC-20 代币于 2021 年 11 月空投给 .eth 域名持有者和贡献者，总量上限为 1 亿枚。","euro-coin":"EURC 是由 USDC 发行方 Circle 推出的欧元稳定币，由欧元储备 1:1 支撑。它于 2022 年推出（最初名为 Euro Coin），并依据欧盟 MiCA 法规作为电子货币代币发行。EURC 用于欧元支付、外汇兑换和 DeFi，覆盖以太坊、Solana、Base、Avalanche 等链。","falcon-finance":"Falcon USD（USDf）是 Falcon Finance 协议发行的合成美元。用户存入稳定币、BTC 或 ETH 等抵押品即可铸造 USDf，系统持有的抵押品价值高于已发行的 USDf。USDf 可作为以美元计价的资产在 DeFi 中使用，也可在协议内质押换取 sUSDf。","falcon-finance-ff":"FF 是 Falcon Finance 的治理和功能代币。该协议发行合成美元 USDf，以加密资产、稳定币和代币化现实资产作为抵押铸造。持有者可质押 FF 获取协议内权益，并对协议参数进行投票。代币于 2025 年推出，可在以太坊和 BNB Smart Chain 上使用。","fetch-ai":"FET 是人工超级智能联盟（ASI Alliance）的代币。该联盟于 2024 年成立，由 Fetch.ai 与 SingularityNET 的 AGIX（最初还包括 Ocean Protocol 的 OCEAN）合并代币而来。FET 用于支付 Fetch.ai 自主 AI 代理网络中的服务费用、质押保障网络安全以及参与治理，存在于以太坊、Cardano、BNB Smart Chain 等网络。","filecoin":"Filecoin（FIL）是由 Protocol Labs 打造的去中心化存储网络的原生代币，主网于 2020 年上线。用户支付 FIL 来存储和取回数据，存储提供者则需质押 FIL 作为抵押，并因持续保存文件而获得 FIL。网络通过复制证明和时空证明等密码学证明，确认数据确实被保存。","first-digital-usd":"First Digital USD（FDUSD）是由 First Digital Labs 发行的美元稳定币，该公司隶属于香港的 First Digital Group，代币于 2023 年推出。每枚 FDUSD 旨在由托管的现金及短期美国国债等现金等价物 1:1 支持。它常用作交易对和支付工具，也用于在以太坊、BNB Smart Chain、Solana、Sui、TON 等链之间转移美元。","flare-networks":"FLR 是 Flare 的原生代币。Flare 是兼容 EVM 的一层区块链，其代币自 2023 年 1 月起开始分发，其中一部分以空投形式发放给 XRP 持有者。Flare 把数据工具直接内置在协议中，例如提供价格数据的 Flare 时间序列预言机（FTSO）和 Flare 数据连接器。FLR 用于支付费用、质押、委托给数据提供者以及治理。","floki":"FLOKI 是 2021 年推出的社区模因币，名字来自马斯克的柴犬。除了模因属性，项目还开发了区块链游戏 Valhalla 和 DeFi 工具 FlokiFi，持有者可参与治理投票。该代币同时存在于以太坊和 BNB Smart Chain 上。","frax":"FRAX 现标注为 Legacy Frax Dollar，是 Frax Finance 最早的美元稳定币，2020 年 12 月推出。它最初采用部分抵押、部分算法的模式，后来转为完全抵押。Frax 之后推出了 frxUSD 作为主要美元稳定币，因此这枚早期代币被标为「旧版」。","gatechain-token":"Gate（GT）是 Gate 交易所生态的代币，2019 年以 GateToken 的名义首次发行。它可用于交易手续费折扣和平台活动，也是该交易所自有区块链的 Gas 代币。Gate 会定期回购并销毁 GT，使总供应量逐步减少。","gho":"GHO 是 Aave 协议于 2023 年推出的去中心化稳定币，目标是锚定美元。用户以存入 Aave 的加密资产作为抵押借出 GHO，因此每一枚 GHO 背后都有价值更高的超额抵押。借款利率等参数由 Aave 治理决定，GHO 可在以太坊及多条其他网络上使用。","global-dollar":"Global Dollar（USDG）是由 Paxos 发行、Global Dollar Network（由多家加密和金融科技公司组成的联盟）支持的美元稳定币。每枚 USDG 由现金及现金等价物储备支持，设计为可按 1:1 兑换美元。它依据新加坡的稳定币监管框架发行，可在以太坊、Solana、Arbitrum 等网络上使用。","gnosis":"GNO 是 Gnosis 的代币。Gnosis 于 2015 年创立，专注以太坊生态，早期孕育了 Safe 多签钱包和 CoW Swap 等工具。如今 GNO 主要用于保障 Gnosis Chain 的安全：这条兼容 EVM 的网络已与原 xDai 链合并，验证者需质押 GNO 出块。持有者还可用 GNO 在 GnosisDAO 中投票，决定金库和项目方向。","grass":"Grass 是一个让用户通过浏览器插件或应用共享闲置网络带宽的网络，这些带宽被用于收集公开网页数据，供 AI 训练使用。GRASS 是该项目在 Solana 上的代币，用于奖励参与者、质押到网络路由节点以及参与治理。代币最早于 2024 年通过社区空投分发。","grx-chain":"GRX 是 GRX Chain 的原生币，该项目运行在自有区块链上，被归入交易所相关代币类别。这类原生币通常用于支付网络交易手续费，以及在项目生态内使用。","hash-2":"HASH 是 Provenance Blockchain 的原生代币。该网络基于 Cosmos SDK 构建，采用权益证明机制，专为贷款、证券和基金登记等金融业务设计，由美国金融科技公司 Figure Technologies 主导创建。HASH 用于支付网络手续费，验证者和委托者通过质押 HASH 维护网络并参与治理投票。","hedera-hashgraph":"HBAR 是 Hedera 网络的原生币。Hedera 是一个公共网络，采用哈希图（hashgraph）共识而非传统区块链结构。HBAR 用于支付交易、智能合约和文件存储费用，也可质押以帮助保障网络安全。Hedera 由多家大型企业和机构组成的理事会治理，手续费低且以美元计价。","htx-dao":"HTX DAO（HTX）是 HTX 交易所（前身为火币）生态的代币。它于 2024 年推出，用于 HTX DAO 的治理投票以及平台内的各项权益。旧的火币代币（HT）持有人可以兑换为 HTX，该代币在波场、以太坊和 BNB Smart Chain 上流通。","hyperliquid":"HYPE是Hyperliquid的原生代币。Hyperliquid是一条Layer 1区块链，核心是链上订单簿，用于永续合约和现货交易。HYPE用于支付网络Gas费、质押给运行HyperBFT共识的验证者，并参与治理。该代币于2024年底推出，其中很大一部分通过空投分发给早期用户。","injective-protocol":"INJ 是 Injective 的原生代币。Injective 是基于 Cosmos SDK 构建的一层区块链，专为订单簿交易、衍生品和现实世界资产代币化等金融应用设计。INJ 用于质押以保障权益证明网络安全，也用于支付费用和参与治理。协议的部分费用会进入定期销毁拍卖，将 INJ 永久移出流通。","instadapp":"FLUID 是 Fluid 的治理代币。Fluid 是原名 Instadapp 的 DeFi 协议，原有的 INST 代币于 2024 年更名为 FLUID。Fluid 将借贷和去中心化交易所建立在共享的流动性层上，同一笔存款既能作为抵押品，也能作为交易流动性。持有者可对协议参数投票，协议运行在以太坊及多条其他网络上。","internet-computer":"ICP 是互联网计算机（Internet Computer）的原生代币。这条区块链由 DFINITY 基金会开发，2021 年上线，可以把完整的网页应用及其数据直接部署在链上。ICP 可转换为支付计算和存储费用的 cycles，也可锁定在 neuron 中参与网络治理投票。以太坊和 Base 上也有其跨链版本。","iota":"IOTA 是 IOTA 网络的原生币，项目始于 2016 年，由总部位于柏林的 IOTA 基金会支持。它最初采用名为 Tangle 的无区块结构，面向物联网和数据场景；2025 年升级为 IOTA Rebased，改用委托权益证明和 Move 智能合约。IOTA 用于支付网络费用和质押。","janus-henderson-anemoy-aaa-clo-fund":"JAAA 是一只基金份额的代币化形式，该基金投资于 AAA 评级的担保贷款凭证（CLO），即打包企业贷款的证券。投资策略由资产管理公司 Janus Henderson 负责，并通过与 Centrifuge 现实资产网络相关的发行方 Anemoy 上链。代币分布在以太坊、Base、Solana 等链上，通常仅向合格投资者开放。","jasmycoin":"JASMY 是日本公司 Jasmy 的代币，该公司由索尼前高管创立，专注于物联网（IoT）设备和个人数据。它希望让用户掌控自己设备产生的数据，并自行决定如何分享。JASMY 是以太坊上的 ERC-20 代币，用于这个数据平台。","jito-governance-token":"JTO 是 Jito 的治理代币。Jito 是 Solana 上的项目，以流动性质押代币 JitoSOL 和处理 MEV（通过交易排序产生的额外价值）的 Jito 验证者客户端而闻名。JTO 持有者在 Jito DAO 中就费率设置、金库用途和协议变更投票。该代币于 2023 年 12 月通过空投分发。","jupiter-exchange-solana":"Jupiter（JUP）是 Solana 上去中心化交易聚合器 Jupiter 的代币，该平台会把兑换请求分配到多个流动性来源，寻找更高效的成交路径。JUP 用于 Jupiter DAO 治理，持有人可就提案和新项目上线投票。该代币于 2024 年 1 月通过大规模社区空投分发。","just":"JUST（JST）是 JUST 的治理代币，JUST 是 2020 年在波场上推出的去中心化金融平台。持有人可就其产品（包括借贷市场 JustLend）的提案投票，JST 也用于支付部分协议费用。平台的部分收入会用于回购并销毁 JST。","kaia":"Kaia（KAIA）是 2024 年由 Klaytn 与 Finschia 合并而成的公链，前者由 Kakao 推出，后者由 LINE 推出，两者都与亚洲大型通讯软件相关。KAIA 取代了原来的 KLAY 和 FNSA 代币，用于支付手续费、质押和治理。该链兼容 EVM，重点面向通过 Kakao、LINE 等通讯软件触达的钱包和小程序。","kamino":"KMNO 是 Kamino Finance 的治理代币。Kamino 是 Solana 上的 DeFi 平台，把借贷、自动化流动性金库和杠杆仓位整合在同一个界面中。持有者可以用 KMNO 对协议事务投票，也可以在 Kamino 内质押。该代币于 2024 年通过空投分发给早期用户。","kaspa":"Kaspa（KAS）是一种基于 blockDAG 结构的工作量证明加密货币，允许多个区块并行产生，而不是排成单一链条。这一基于 GHOSTDAG 协议的设计带来了很短的出块时间和快速确认。KAS 用于支付和交易手续费，网络于 2021 年 11 月公平启动，没有预挖。","kinesis-gold":"Kinesis Gold（KAU）是一种黄金支撑的数字货币，每枚代币代表金库中一克已分配的实物黄金。它属于 Kinesis 货币体系，该体系会将部分交易费用作为收益分给持有者和使用者。KAU 可以持有、转账或消费，并可按平台规则赎回实物黄金。","kinesis-silver":"KAG 是 Kinesis 发行的代币，每枚代表存放在分配式金库中的一金衡盎司实物白银。它让人们可以用数字方式持有、转账和使用白银，并可按发行方条款兑换实物。KAG 在 Kinesis 体系中用于支付和保存价值，并在以太坊上有对应版本。","kite-2":"KITE 是 Kite 的原生代币。Kite 是专注 AI 智能体支付与身份的区块链，让自主运行的软件拥有可验证身份并自行支付服务费用。它是基于 Avalanche 技术构建的 EVM 兼容网络，KITE 用于质押、网络安全、治理和生态激励，并在以太坊、BNB Smart Chain 和 Hyperliquid 上有对应版本。","kucoin-shares":"KuCoin Token（KCS）是 KuCoin 交易所的原生代币，于 2017 年推出。持有人可用它享受交易手续费折扣等平台权益，它也是 KuCoin 社区链 KCC 的 Gas 代币。KuCoin 定期回购并销毁 KCS，长期计划将总量减少到 1 亿枚。","layerzero":"ZRO 是 LayerZero 的代币。LayerZero 是一个跨链互操作协议，让应用可以在不同区块链之间传递消息和代币。它本身不是独立的公链，而是在以太坊、Arbitrum、Base、BNB Smart Chain 等多条网络上部署端点合约。ZRO 于 2024 年发行，主要用于协议治理。","leo-token":"LEO Token（LEO）是Bitfinex交易平台母公司iFinex于2019年推出的功能型代币。持有者可在Bitfinex及相关平台用LEO降低交易费并享受其他权益。iFinex承诺持续回购并销毁LEO，使流通量逐步减少。该代币发行在以太坊等网络上。","lido-dao":"LDO 是 Lido 的治理代币。Lido 是一项流动性质押服务，用户质押 ETH 后可获得 stETH，在累积质押奖励的同时仍可在 DeFi 中使用。LDO 持有者在 Lido DAO 中就协议参数、节点运营商选择和金库支出投票。该代币于 2020 年底在以太坊上发行，并已桥接到多个二层网络。","lighter":"LIT 是 Lighter 的原生代币。Lighter 是一个专注于永续合约交易的去中心化交易平台，以零知识 Rollup 的形式运行在以太坊上，用密码学证明来确认订单撮合与结算是正确的。LIT 发行在以太坊上，同时也存在于 Robinhood Chain。","litecoin":"莱特币（LTC）是最早的加密货币之一，由Charlie Lee于2011年推出，定位为更轻、更快的比特币变体。它运行在自己的工作量证明区块链上，采用Scrypt算法，约每2.5分钟产生一个新区块。LTC主要用于支付和转账，总量上限为8400万枚，是比特币的四倍。","mantle":"Mantle（MNT）是 Mantle Network 的原生代币。Mantle Network 是一条以太坊二层网络，会把交易打包后结算到以太坊上。MNT 用于支付 Mantle 上的 Gas 费，并可参与治理投票。该项目源自 BitDAO，2023 年 BIT 代币被转换为 MNT。","memecore":"MemeCore（M）是一个围绕 Meme 文化打造的项目，自我定位为专为 Meme 币及其社区服务的区块链。M 代币属于 Meme 类别，目前以代币形式存在于 BNB Smart Chain 上。","meteora":"MET 是 Meteora 的代币。Meteora 是 Solana 上的流动性协议，其资金池被交易者、新代币发行和其他 DeFi 应用广泛使用。它以动态资金池著称，其中 DLMM 设计把流动性放在不同价格区间，并根据市场波动调整手续费。MET 于 2025 年推出，用于协议治理。","midnight-3":"NIGHT 是 Midnight 的原生代币。Midnight 是由 Cardano 背后团队开发、以 Cardano 合作链形式运行的隐私区块链，利用零知识证明让应用既能保护敏感数据，又能证明规则已被遵守。持有 NIGHT 会产生 DUST，这是一种专门用于支付交易费用的隐私资源；NIGHT 本身则用于治理和出块。","monad":"Monad（MON）是 Monad 的原生代币。Monad 是兼容以太坊的一层公链，于 2025 年 11 月上线主网。它通过并行执行交易和自研的 MonadBFT 共识追求高吞吐量，同时可直接运行标准的以太坊智能合约。MON 用于支付 Gas 费，并由验证者和委托者质押以保障网络安全。","monero":"门罗币（XMR）是2014年推出的隐私型加密货币，默认对交易细节保密。它结合环签名、隐身地址和保密交易，隐藏发送方、接收方和金额。门罗币采用适合普通CPU的RandomX工作量证明算法挖矿，主要供应发行完毕后，仍保留少量永久区块奖励（尾部发行）。","morpho":"MORPHO 是 Morpho 的治理代币，Morpho 是部署在以太坊及 Base 等 EVM 网络上的去中心化借贷协议。任何人都可以在 Morpho 上创建相互隔离的借贷市场，由第三方策展人管理的金库再把存款分配到这些市场。MORPHO 持有人通过 Morpho DAO 就协议升级和财库事项投票。","mx-token":"MX 是中心化加密货币交易所 MEXC（抹茶）的平台币，MEXC 成立于 2018 年。持有或使用 MX 可享受交易手续费折扣，参与平台的新币发行活动，并参与上币投票。它以 ERC-20 代币形式发行在以太坊上，也存在于 Morph L2。","near":"NEAR Protocol（NEAR）是2020年上线的权益证明Layer 1区块链，采用Nightshade分片设计分担网络负载。NEAR用于支付交易和存储费用，并可质押给验证者。项目近年聚焦AI与用户自主的智能体，联合创始人Illia Polosukhin是论文《Attention Is All You Need》的作者之一。","neo":"NEO 是 Neo 区块链的原生币。Neo 是 2014 年在中国创立的智能合约平台，最初名为小蚁（Antshares），2017 年更名。它采用委托拜占庭容错（dBFT）共识机制。NEO 用于治理，包括选举负责共识的委员会；持有 NEO 还会产生 GAS，用于支付网络手续费。NEO 总量固定为 1 亿枚，且不可分割。","nexo":"NEXO 是 Nexo 平台的代币，Nexo 是一家成立于 2018 年的加密借贷与数字资产平台。用户在平台上持有的 NEXO 数量决定其会员等级，进而影响借款利率等账户权益。NEXO 最初是以太坊上的 ERC-20 代币，目前也可在 Polygon 等多条网络上使用。","non-playable-coin":"Non-Playable Coin（NPC）是一个 Meme 代币，名字来自网络上的“NPC”梗，调侃有些人像游戏里的背景角色一样随大流。它于 2023 年在以太坊上推出，设计上可以在代币与关联的 NFT 系列之间相互转换。之后它被桥接到 Solana、BNB Smart Chain、Base 等网络。","official-trump":"Official Trump（TRUMP）是 Solana 上与唐纳德·特朗普相关的 Meme 代币，于 2025 年 1 月其就职前夕推出。它没有手续费、质押等协议用途，主要作为收藏和社区代币。相当一部分供应量分配给了关联实体，并按多年解锁计划逐步释放。","okb":"OKB 是 OKX 生态的功能型代币，可用于交易手续费折扣和平台权益，同时也是 OKX 自有二层网络 X Layer 的 Gas 代币。2025 年的一次大规模销毁将 OKB 总供应量固定为 2,100 万枚，此后不会再增发。","olympus":"OHM 是 Olympus 的代币。Olympus 是 2021 年在以太坊上推出的 DeFi 协议，维护一个用于支撑代币的资产金库。协议通过回购和区间机制管理 OHM 供应，持有者还可通过 Cooler Loans 功能以质押的 OHM 为抵押借入稳定币。OHM 同时也是 OlympusDAO 的治理代币。","ondo-finance":"ONDO 是 Ondo Finance 的治理代币。Ondo Finance 致力于将美国国债基金等传统金融资产以代币形式带到区块链上。ONDO 持有者可参与 Ondo 生态及其产品相关的决策。该代币运行在以太坊上，Ondo 的代币化产品同时面向机构和普通链上用户。","open-usd":"Open USD（OUSD）是一种旨在维持 1 美元价值的稳定币。它以代币形式发行在以太坊、Solana、Base 和 Tempo 等多条网络上，可用于支付、转账，或在链上应用中作为美元余额。","optimism":"OP 是 Optimism Collective 的治理代币。其管理的 OP Mainnet 是以太坊二层网络，采用乐观汇总（Optimistic Rollup）打包交易并在以太坊上结算。持有者在代币院（Token House）就升级、激励计划和资助投票，而 OP Mainnet 的手续费用 ETH 而非 OP 支付。代币于 2022 年推出，同一套 OP Stack 还支撑着名为 Superchain 的多条链。","origintrail":"TRAC 是 OriginTrail 的代币。OriginTrail 运行一个去中心化知识图谱（DKG），用于发布和关联可验证的数据，应用于供应链、AI 等领域。在网络上发布“知识资产”需要消耗 TRAC，节点运营者则质押 TRAC 来存储和提供这些数据。它是以太坊上的 ERC-20 代币，在 Base 上也有版本。","pancakeswap-token":"CAKE 是 PancakeSwap 的代币。PancakeSwap 是 2020 年在 BNB Smart Chain 上线的去中心化交易平台，之后扩展到以太坊、Arbitrum、Base、Aptos 等网络。用户通过自动化流动性池兑换代币，CAKE 用于流动性激励、质押和治理投票。平台部分手续费会用于回购并销毁 CAKE，以减少供应量。","pax-gold":"PAX Gold（PAXG）是由美国受监管信托公司 Paxos 于 2019 年发行的黄金代币。每枚代币对应存放在专业金库中、符合伦敦合格交割标准的一金衡盎司纯金的所有权。它是以太坊上的 ERC-20 代币，方便持有和转账，也可以按很小的份额持有黄金。","paypal-usd":"PayPal USD（PYUSD）是 Paxos 为 PayPal 发行的美元稳定币，于 2023 年推出。每枚代币由美元存款、短期美国国债及类似现金等价物支持，设计为可按 1:1 兑换。PYUSD 可在 PayPal 和 Venmo 内转账和消费，也在以太坊、Solana、Arbitrum 等区块链上流通。","pearl-2":"Pearl（PRL）是其自有区块链的原生币，被归入 AI 类别。与多数一层公链代币一样，PRL 用于支付网络手续费并支持链的运行。","pendle":"Pendle 是 2021 年上线的 DeFi 协议，可将生息资产拆分为本金代币（PT）和收益代币（YT）两部分并分别交易。这样用户既可以锁定固定收益，也可以对未来收益率表达观点。PENDLE 代币用于治理，可质押或锁定以获得协议收入分成并引导激励分配。","pepe":"Pepe（PEPE）是 2023 年 4 月在以太坊上推出的 Meme 币，名字来自网络表情「青蛙佩佩」（Pepe the Frog）。它没有正式路线图，除了作为社区代币被交易和传播外，也没有内置用途。约 420.69 万亿枚的固定供应量在发行时全部释放，其他链上也有跨链版本。","pi-network":"Pi（PI）是 Pi Network 的原生币。该项目于 2019 年启动，让用户通过手机应用累积代币，而不是依靠高耗能的挖矿。开放主网于 2025 年 2 月上线，此前多年余额只能在应用生态内使用。网络共识基于恒星共识协议（SCP），用户通常需要先完成身份验证，才能把代币迁移到主网。","pieverse":"PIEVERSE 是 Pieverse 项目的代币，属于 AI 赛道，主要为 AI 智能体搭建基础设施，包括链上支付等功能。代币发行在 BNB Smart Chain 和以太坊上，用于参与 Pieverse 生态。","plasma":"Plasma 是专为稳定币支付（尤其是 USDT）设计的一层区块链，支持 USDT 零手续费转账等功能。它兼容 EVM，并将状态锚定到比特币以增强安全性，主网测试版于 2025 年 9 月上线。XPL 是其原生代币，用于支付其他操作的交易费用，并由验证者质押以保障网络安全。","polkadot":"DOT 是波卡（Polkadot）的原生币。波卡由以太坊联合创始人 Gavin Wood 创立，把众多专用区块链连接到一个共享安全层上。DOT 用于链上治理、在提名权益证明（NPoS）机制下质押，以及为接入的链获取区块空间。波卡主网于 2020 年上线。","polygon-ecosystem-token":"POL 是 Polygon 网络的原生代币，也是 MATIC 的升级版，持有人自 2024 年 9 月起按 1:1 迁移。POL 用于支付 Polygon PoS 上的 Gas 费，并由验证者质押以保障网络安全。它的设计还可服务于通过 Polygon AggLayer 连接的其他链。","pudgy-penguins":"PENGU 是 Pudgy Penguins（胖企鹅）的代币。该卡通企鹅品牌 2021 年起源于以太坊 NFT 系列，后来拓展到玩具和媒体领域。PENGU 于 2024 年 12 月在 Solana 上推出，并向 NFT 持有者及其他加密社区广泛空投。它主要作为社区和 Meme 代币，现已覆盖多条网络。","pump-fun":"PUMP 是 Pump.fun 平台的代币。Pump.fun 是基于 Solana 的平台，任何人都能在几步之内创建并发行 Meme 币，早期交易通过联合曲线（bonding curve）进行。PUMP 于 2025 年推出，与平台生态和社区紧密相关。它是 Solana 代币，需存放在支持 Solana 的钱包中。","pyth-network":"PYTH 是 Pyth Network 的代币。Pyth 是一个为区块链应用提供市场价格的预言机，数据直接来自交易所、交易机构等一手发布者。网络最初建立在 Solana 上，之后扩展到众多其他公链。PYTH 用于治理，以及通过质押机制让数据发布者对其报价质量负责。","quant-network":"QNT 是 Quant 的代币。Quant 公司的 Overledger 技术旨在连接不同的区块链以及现有的企业系统。企业和开发者使用 QNT 支付许可证费用和网络接入费用。该代币运行在以太坊上，供应量有上限，约为 1,460 万枚。","railgun":"RAIL 是 Railgun 的治理代币。Railgun 是面向以太坊及其他 EVM 网络的隐私协议，利用零知识证明，让用户在“屏蔽”余额中持有、转账和兑换代币，而不公开暴露地址历史。RAIL 持有者通过质押参与协议投票，并分享资产进出隐私系统时收取的费用。","rain":"Rain（RAIN）是去中心化金融（DeFi）领域的代币，发行在以太坊二层网络Arbitrum One上。作为Arbitrum代币，它可在兼容以太坊的钱包和应用中转账使用，网络费用以ETH而非RAIN支付。","raydium":"RAY 是 Raydium 的代币。Raydium 是 2021 年在 Solana 上线的自动做市商（AMM）和流动性平台，用户可以兑换代币、为资金池提供流动性，许多 Solana 新代币的首个交易池都建在 Raydium 上。RAY 用于质押和流动性激励，部分交易手续费会用于回购 RAY。","re-protocol-reusd":"reUSD 是 Re Protocol 推出的美元计价代币。Re Protocol 把链上资金与再保险市场连接起来——再保险即保险公司把部分风险转移给其他机构。reUSD 旨在保持稳定的美元价值，并由再保险相关资产支持。它可在以太坊、Solana、Arbitrum、Base、Avalanche 等多个网络上使用。","render-token":"Render（RENDER）是 Render Network 的代币，该网络把需要 GPU 算力进行 3D 渲染和 AI 任务的用户，与拥有闲置 GPU 的节点运营者连接起来。创作者用 RENDER 支付任务费用，运营者完成工作后获得 RENDER。项目由 OTOY 创始人 Jules Urbach 发起，2023 年从以太坊迁移至 Solana，取代旧的 RNDR 代币。","ripple":"XRP是XRP Ledger（XRP账本）的原生资产，该公链于2012年上线，与Ripple公司关系密切。它专为快速、低成本的支付和跨境结算设计，交易通过共识机制而非挖矿在几秒内确认。全部1000亿枚XRP在上线时一次性创建，每笔交易都会销毁极少量费用。","ripple-usd":"Ripple USD（RLUSD）是 Ripple 于 2024 年 12 月推出的美元稳定币，由美元存款、短期美国国债及现金等价物支持，设计为可按 1:1 兑换。RLUSD 在 XRP Ledger 和以太坊上原生发行，主要面向支付和机构用途。","safo":"SAFO 是一种代币化基金份额，由巴黎金融科技公司 Spiko 提供，底层基金由资产管理公司 Amundi（东方汇理）管理。该基金通过掉期合约跟踪隔夜利率，代币让符合条件的投资者在公链上持有和转移基金份额。它发行在以太坊、Arbitrum、Base、Polygon、Starknet 和 Stellar 等多个网络。","sei-network":"Sei 是为高速交易类应用打造的一层区块链，具备亚秒级最终确认和并行交易处理能力。自 v2 升级后，它运行并行化 EVM，可直接部署以太坊风格的智能合约。SEI 用于支付 Gas、质押保障权益证明网络安全以及参与治理，主网于 2023 年 8 月上线。","shiba-inu":"柴犬币（SHIB）是 2020 年由化名 Ryoshi 的匿名创建者推出的 Meme 代币，名字来自因狗狗币而走红的柴犬。它最初是以太坊上的 ERC-20 代币，后来发展出包含去中心化交易所 ShibaSwap 和二层网络 Shibarium 的社区生态。SHIB 供应量达数百万亿枚，其中一部分已被销毁。","shuffle-2":"SHFL 是 Shuffle 的代币。Shuffle 是一个接受加密货币的在线游戏平台。SHFL 是以太坊上的 ERC-20 代币，在平台内用于奖励计划和面向持币者的抽奖等功能，其作用与 Shuffle 平台本身紧密相关，而不是一条独立的区块链。","sky":"Sky（SKY）是 Sky 协议的治理代币，Sky 是 MakerDAO 在 2024 年更名后的新品牌。持有人可就协议的风险参数和抵押品投票，该协议发行 USDS 稳定币以及原有的 DAI。SKY 是 MKR 的升级版本，每 1 枚 MKR 可兑换 24,000 枚 SKY。","societe-generale-forge-eurcv":"EUR CoinVertible（EURCV）是法国兴业银行（Société Générale）旗下数字资产子公司 Societe Generale-FORGE 发行的欧元稳定币。每枚代币设计为价值 1 欧元，由发行方持有的欧元储备支持。它于 2023 年首先在以太坊上推出，现已扩展到 Solana、Stellar 和 XRP Ledger，用于支付与结算。","sofiusd":"SoFiUSD 是由美国消费金融公司 SoFi 发行的美元稳定币，SoFi 持有美国国家银行牌照。它设计为可按 1:1 兑换美元，并由发行方持有的储备支持，是少数由受监管的美国银行直接发行的稳定币之一。它运行在以太坊和 Solana 上，主要面向支付和结算。","solana":"Solana（SOL）是2020年上线的Solana公链的原生代币，主打高吞吐量与低手续费。SOL用于支付链上交易费，并可质押给验证节点，通过权益证明（PoS）机制维护网络安全；“历史证明”（Proof of History）时间戳机制则帮助高效排序交易。","sonic-3":"S 是 Sonic 的原生币。Sonic 原名 Fantom，2024 年底以新名称和升级后的链重新上线，FTM 持有者可按 1:1 兑换为 S。S 用于支付交易费、质押保障网络和参与治理。Sonic 兼容 EVM，并让应用开发者分得其应用产生的部分手续费。","spiko-amundi-overnight-swap-fund-eur":"EURSAFO 是巴黎金融科技公司 Spiko 与资产管理公司 Amundi 合作推出的欧元基金的代币化份额。每枚代币代表一份基金份额，其价值旨在跟随欧元隔夜利率，份额直接登记在公链上。它在以太坊、Arbitrum、Base、Polygon、Starknet 和 Stellar 等多个网络上发行。","stable-2":"STABLE 是 Stable 的原生代币。Stable 是专为稳定币支付打造的一层区块链，以 USDT 为核心。在 Stable 上，交易手续费直接用 USDT 支付，而不是另一种 Gas 代币，普通用户无需额外持有其他代币就能转账美元。STABLE 则承担另一项职能：支持网络安全与治理。","starknet":"STRK 是 Starknet 的原生代币，Starknet 是由 StarkWare 开发的以太坊二层网络。它属于有效性 Rollup：把大量交易打包，并用 STARK 密码学证明向以太坊证明其正确性，智能合约使用 Cairo 语言编写。STRK 于 2024 年发行，用于支付交易费、质押和治理。","stellar":"恒星币（XLM）是Stellar网络的原生资产，该网络由Jed McCaleb和非营利的Stellar发展基金会于2014年推出，专注于支付和发行稳定币等代币化资产，采用Stellar共识协议而非挖矿。XLM用于支付少量交易费，每个账户也需保留最低余额。","sui":"SUI 是 Sui 公链的原生币。Sui 是由 Mysten Labs 开发的一层区块链，创始团队来自 Meta 的 Diem 项目。SUI 用于支付交易手续费、质押给验证节点以保障网络安全，并参与治理。Sui 主网于 2023 年上线，采用 Move 编程语言，最大供应量为 100 亿枚。","sun-token":"SUN 是 SUN.io 的治理代币。SUN.io 是波场（TRON）上的 DeFi 平台，提供稳定币兑换、流动性池以及 SunSwap 去中心化交易功能。持有者可以锁定 SUN 参与提案投票，并提高自己在平台流动性挖矿中的份额。该项目于 2020 年在波场创始人孙宇晨的生态中推出。","swissborg":"BORG 是 SwissBorg 的代币。SwissBorg 是一款总部位于瑞士、成立于 2017 年的加密投资应用。BORG 在 2024 年的迁移中取代了原来的 CHSB 代币，在应用内用于解锁更高的会员等级和其他权益。它发行在以太坊和 Solana 上。","syrup":"SYRUP 是 Maple Finance 的代币。Maple 是面向机构提供贷款的链上借贷平台，推出了 syrupUSDC 等产品。SYRUP 于 2024 年取代了 Maple 原先的 MPL 代币，每 1 枚 MPL 可兑换 100 枚 SYRUP。持有者可以质押 SYRUP 并参与协议治理。","terra-luna":"Terra Luna Classic（LUNC）是原 Terra 区块链的原生代币。2022 年 5 月，算法稳定币 UST 脱锚导致该链崩盘，之后新链沿用 LUNA 名称，旧链及其代币则更名为 Terra Classic 和 LUNC。这条基于 Cosmos SDK 的网络目前由社区维护，LUNC 用于手续费、质押和治理，包括对代币销毁方案的投票。","tether":"泰达币（USDT）是Tether公司自2014年起发行的稳定币，目标是与1美元保持等值。该公司表示，每枚代币都有储备支持，储备主要为短期美国国债及现金等价物。USDT广泛用于交易、支付和在不同平台间转移美元，并发行在以太坊、波场（TRON）、Solana等多条网络上。","tether-gold":"Tether Gold（XAUT）是 Tether 发行的黄金代币，每枚代表对存放在瑞士金库中一金衡盎司实物黄金的所有权。它让人们可以在区块链上持有和转移黄金，并可按很小的份额持有。XAUT 以以太坊代币形式运行，持有者可以查询分配到自己地址的具体金条。","tezos":"Tezos（XTZ）是一条 2018 年上线主网的公链，采用流动权益证明：持币者可以亲自出块（称为“烘焙”），也可以委托给烘焙者。协议升级由持币者在链上提案和投票决定，因此无需硬分叉即可演进。XTZ 用于支付交易和智能合约手续费。","the-graph":"The Graph（GRT）是一个去中心化索引协议的代币。该协议把区块链数据整理成名为子图（subgraph）的开放 API，应用可直接查询，无需自建数据服务器。索引者质押 GRT 提供服务，委托者把 GRT 委托给索引者，策展者用 GRT 标记有用的子图；查询费也以 GRT 支付。主网于 2020 年 12 月上线。","the-open-network":"Gram（GRAM）原名 Toncoin，是 The Open Network（TON）的原生币。TON 是一条权益证明区块链，最初由 Telegram 团队设计，现由独立社区开发。GRAM 用于支付网络手续费、供验证者质押，也用于 Telegram 生态内的支付和小程序。以太坊和 BNB Smart Chain 上也有其封装版本。","the-sandbox":"SAND 是 The Sandbox 的代币。The Sandbox 是 Animoca Brands 旗下的虚拟世界与游戏创作平台，玩家可以在数字土地上搭建、拥有并运营自己的内容。SAND 用于购买土地（LAND）和游戏资产、支付平台费用，以及质押和治理投票。它是以太坊上的 ERC-20 代币，在 Polygon 和 Base 上也有版本。","theta-token":"THETA 是 Theta Network 的治理和质押代币。Theta 是 2019 年上线的区块链，最初用于去中心化视频传输，近年通过 EdgeCloud 服务扩展到 AI 和 GPU 计算。Theta 采用双代币：THETA 由验证节点和守护节点质押以保障安全，TFUEL 用于支付交易和服务费用。THETA 总量固定为 10 亿枚。","thorchain":"RUNE 是 THORChain 的原生资产。THORChain 让用户直接跨链兑换原生币，例如用 BTC 换 ETH，无需封装代币。每个流动性池都由一种资产与 RUNE 配对，节点运营者必须绑定 RUNE，为存放用户资金的金库提供安全保障。THORChain 基于 Cosmos SDK 构建，2021 年开始跨链交易。","tradable-na-rent-financing-platform-sstn":"该代币代表一份代币化的私人信贷头寸，对应北美一项为房租支付提供融资的信贷安排，通过 Tradable 平台发行。它运行在以太坊二层网络 zkSync 上，一般面向机构和合格投资者，而非日常交易。代码 PC0000031 是产品编号，而不是常见的加密货币简称，持有通常仅限符合条件的参与者。","tron":"波场（TRX）是TRON区块链的原生币，由孙宇晨于2017年创立。TRX用于获取带宽和能量等网络资源，也可质押后投票选出27个超级代表，由他们在委托权益证明机制下出块。波场是转账USDT稳定币最常用的网络之一。","true-usd":"TrueUSD（TUSD）是一种美元稳定币，于 2018 年推出，设计上可按 1:1 兑换储备中的美元。它最初由 TrustToken 团队创建，现由 Techteryx 发行，储备情况通过第三方鉴证报告披露。TUSD 用于支付、交易对和 DeFi，运行在以太坊、TRON、BNB Smart Chain 等网络上。","trust-wallet-token":"TWT 是 Trust Wallet 的代币。Trust Wallet 是一款自托管加密钱包应用，2018 年被币安收购。TWT 于 2020 年推出，用于应用内的手续费折扣等权益以及参与社区功能。它最初发行在较早的 BNB Beacon Chain 上，现在主要运行在 BNB Smart Chain 上。","unibase":"UB 是 Unibase 的代币。Unibase 是一个 AI 方向的项目，定位为 AI 智能体的去中心化记忆层，让智能体能在不同应用之间保存和共享长期数据。代币发行在 BNB Smart Chain 和以太坊上，用于生态内的访问、激励和参与。项目较新，代币模型细节仍可能变化。","uniswap":"UNI 是 Uniswap 的治理代币。Uniswap 是一个去中心化交易所，用户直接用钱包通过自动化流动性池兑换代币，而不是依靠订单簿。UNI 持有者可对协议变更和社区金库用途进行投票。该代币于 2020 年通过向早期用户空投发行，Uniswap 之后还推出了自己的以太坊二层网络 Unichain。","united-stables":"United Stables（U）是一种旨在保持 1 美元价值的稳定币。与其他美元稳定币一样，它可用于在钱包和平台之间转移价值、进行交易，以及在 DeFi 中作为稳定的计价单位。它在 BNB Smart Chain、以太坊和波场等多个网络上发行。","usa":"USAT 是一种美元稳定币，设计目标是与美元保持 1:1 的价值，可在以太坊和 Celo 上使用。这类稳定币用于在链上转移美元价值、支付与结算，并在交易和 DeFi 中充当稳定资产。储备支持和赎回条款由发行方设定，建议阅读发行方自己的披露信息。","usd-coin":"USDC是Circle公司于2018年推出的美元稳定币。每枚代币设计为可按1:1兑换美元，由现金和短期美国国债支持，储备情况定期公布。USDC用于交易、支付和DeFi，并在以太坊、Sui、Hedera、XRP Ledger等多条区块链上原生发行。","usd1-wlfi":"USD1 是 World Liberty Financial 于 2025 年推出的美元稳定币。每枚代币设计为可按 1:1 兑换美元，由现金、短期美国国债及现金等价物储备支持，并由 BitGo 托管。它已在以太坊、BNB Smart Chain、Solana、TRON 等多条网络上发行。","usdai":"USDai 是 USD.AI 协议发行的锚定美元代币，该协议把链上资金引导至以 GPU 等 AI 算力硬件为抵押的贷款。用户可将 USDai 作为稳定的计价单位持有，也可在协议中质押，换取与这项借贷业务挂钩的质押版本。该代币流通于 Arbitrum、以太坊、Base 和 Plasma。","usdd":"USDD 是一种美元稳定币，2022 年在波场（TRON）网络上推出。它的目标是锚定 1 美元，并以价值高于流通量的加密资产储备作为支撑。USDD 主要用于波场 DeFi 生态中的支付、交易对和借贷，也在以太坊和 BNB Smart Chain 上发行。","usdgo":"USDGO 是一种旨在与美元 1:1 挂钩的稳定币。它的用途与其他美元稳定币类似：持有稳定余额、在钱包之间转移价值，以及在交易和 DeFi 中作为计价单位。它在 Solana、以太坊和 Morph L2 上发行。","usds":"USDS是Sky（原MakerDAO）发行的美元稳定币，于2024年作为DAI的升级版推出，DAI与USDS可按1:1互换。USDS以协议中锁定的抵押品生成，抵押品包括加密资产和现实世界资产，目前流通于以太坊、Base、Arbitrum和Solana等网络。","usdtb":"USDtb 是 USDe 背后的团队 Ethena 于 2024 年底推出的美元稳定币。与 USDe 不同，它主要由贝莱德代币化美国国债基金 BUIDL 的份额及类现金储备支撑，而不是对冲后的加密资产头寸。它被用作稳定的结算资产，也是支撑 Ethena 其他产品的储备之一。","useless-3":"Useless Coin（USELESS）是 2025 年在 Solana 上推出的 Meme 代币，公开宣称自己“没有任何用处”。它的吸引力来自这个玩笑本身以及围绕它形成的网络社区，而不是某个产品或协议。该代币在 BNB Smart Chain 上也有版本。","usual-usd":"USD0 是 Usual 协议发行的美元稳定币，设计上由代币化美国短期国债等现实资产 1:1 支撑。用户可将 USD0 存入 Usual 的质押产品以获得协议代币 USUAL，USD0 也被用作 DeFi 借贷和流动性池的基础资产。它运行在以太坊及多条 EVM 链上。","usx":"USX 是发行在 Solana 上的稳定币，目标是让每枚代币保持约 1 美元的价值。与其他美元稳定币一样，它主要用于支付、在不同应用之间转移资金，以及在 DeFi 协议中充当稳定的计价单位。其锚定方式和背后资产由发行方设定，使用前建议查看发行方公布的储备或抵押信息。","vaulta":"Vaulta（A）是 Vaulta 网络的原生币，该链前身为 EOS，2025 年完成品牌升级，EOS 按 1:1 兑换为 A。网络采用委托权益证明（DPoS），定位于 Web3 银行与支付服务。A 用于支付链上资源，也可质押参与网络安全。","vechain":"VET 是唯链 VeChainThor 的原生代币。VeChainThor 是 2018 年上线的公链，侧重供应链溯源和企业应用。唯链采用双代币模型：持有 VET 会产生 VTHO，而真正用来支付交易费的是 VTHO。该网络长期采用权威证明式共识，由身份公开并经过审核的验证节点出块。","venice-token":"Venice Token（VVV）是 Venice.ai 的代币。Venice.ai 是由 Erik Voorhees 创立、注重隐私的 AI 平台，运行开源模型且不保存用户对话。质押 VVV 可获得一部分 Venice AI API 的使用额度，无需按次付费。该代币于 2025 年 1 月在以太坊二层网络 Base 上推出。","virtual-protocol":"Virtuals Protocol 是一个创建和共同拥有 AI 代理的平台，主要运行在 Base 上，每个代理都可以拥有自己的代币。VIRTUAL 是该生态的基础资产：新的代理代币在流动性池中与 VIRTUAL 配对，它也用于支付代理服务和发行费用。项目前身是游戏公会 PathDAO，于 2024 年更名为 Virtuals。","whitebit":"WhiteBIT Coin（WBT）是加密货币交易平台WhiteBIT的功能型代币，该平台创立于乌克兰。持有者可在WhiteBIT生态中使用WBT获得权益，例如降低交易费和使用平台功能。该代币最初发行在以太坊和波场上，也用于WhiteBIT团队开发的区块链Whitechain。","world-liberty-financial":"WLFI 是 World Liberty Financial 的治理代币，这是一个 2024 年推出、与美国总统唐纳德·特朗普家族有关的去中心化金融项目。持有人可就平台及产品相关提案投票，其产品包括 USD1 稳定币。该代币最初不可转让，2025 年起开放交易。","worldcoin-wld":"WLD 是 World（原名 Worldcoin）项目的代币，该项目由 Sam Altman 联合创立、Tools for Humanity 开发。它希望为每个人提供注重隐私的“真人”数字证明 World ID，通过名为 Orb 的虹膜扫描设备完成验证。WLD 用于治理和生态激励，运行在以太坊、Optimism 和 World Chain 上。","wormhole":"W 是 Wormhole 的治理代币。Wormhole 是一个跨链消息协议，让 Solana、以太坊等众多区块链之间可以互相传递数据和代币，跨链消息由 19 个被称为 Guardian 的独立验证方共同确认。W 于 2024 年通过大规模社区空投推出，设计为原生多链代币，可在不同网络间转移而无需包装。","xdce-crowd-sale":"XDC 是 XDC Network 的原生币。XDC Network 是由 XinFin 推出的兼容 EVM 的区块链，主要面向贸易融资和现实世界资产代币化，采用名为 XDPoS 的委托权益证明机制，由主节点快速、低成本地出块。XDC 用于支付交易费，并由主节点运营者质押；本页 ID 中的 XDCE 指的是项目早期众售时发行的代币。","ylds":"YLDS 是由 Figure 发行、运行在 Provenance 区块链上的生息美元代币。与多数稳定币不同，它在美国 SEC 注册为证券，并向持有者支付利息，储备资产为短期高质量资产。它面向既需要美元计价代币、又希望获得利息的支付和结算场景。","zama":"ZAMA 是 Zama 协议的代币。Zama 是一家以全同态加密（FHE）技术闻名的密码学公司，FHE 允许数据在保持加密的状态下被计算。Zama 借助这项技术，为现有区块链加入保密余额和隐私智能合约。该代币用于支付协议服务费用，也由运行网络的运营方质押。","zcash":"大零币（Zcash，ZEC）是2016年推出的隐私型加密货币，运行在自己的工作量证明区块链上。它利用零知识证明（zk-SNARKs），让用户可以发送隐藏发送方、接收方和金额的“屏蔽交易”，而透明交易则与比特币类似。ZEC可用于支付，总量上限为2100万枚。","zebec-network":"ZBCN 是 Zebec Network 的代币。这是一个起源于 Solana 的支付项目，以流式支付闻名，即资金按秒持续流向收款人，可用于发薪等场景。项目还在做加密卡等连接数字资产和日常支付的产品。ZBCN 用于生态治理和质押，取代了早期的 ZBC 代币。"});
